const fs = require('fs');
const path = require('path');
const dataFilePath = path.join(__dirname, 'data.json');

// Valid statuses
const validStatuses = ['pending', 'in-progress', 'resolved', 'rejected'];

// Helper function to read data from JSON file
const readData = () => {
    try {
        const data = fs.readFileSync(dataFilePath, 'utf8');
        return JSON.parse(data);
    } catch (error) {
        if (error.code === 'ENOENT') {
            return [];
        }
        throw error;
    }
};

// Helper function to write data to JSON file
const writeData = (data) => {
    fs.writeFileSync(dataFilePath, JSON.stringify(data, null, 2));
};

// Create a new service request
const createRequest = (title, description, status = 'pending') => {
    if (!title || !description) {
        throw new Error('Title and description cannot be empty');
    }

    if (!validStatuses.includes(status)) {
        throw new Error(`Invalid status. Must be one of: ${validStatuses.join(', ')}`);
    }

    const requests = readData();
    const newRequest = {
        id: Date.now().toString(),
        title,
        description,
        status,
        createdAt: new Date().toISOString()
    };

    requests.push(newRequest);
    writeData(requests);
    return newRequest;
};

// List all service requests
const listRequests = () => {
    return readData();
};

// Filter requests by status
const filterByStatus = (status) => {
    if (!validStatuses.includes(status)) {
        throw new Error(`Invalid status. Must be one of: ${validStatuses.join(', ')}`);
    }

    const requests = readData();
    return requests.filter(request => request.status === status);
};

// Update request status
const updateStatus = (id, newStatus) => {
    if (!validStatuses.includes(newStatus)) {
        throw new Error(`Invalid status. Must be one of: ${validStatuses.join(', ')}`);
    }

    const requests = readData();
    const requestIndex = requests.findIndex(request => request.id === id);

    if (requestIndex === -1) {
        throw new Error(`Request with ID ${id} not found`);
    }

    requests[requestIndex].status = newStatus;
    requests[requestIndex].updatedAt = new Date().toISOString();
    writeData(requests);
    return requests[requestIndex];
};

// CLI interface
if (require.main === module) {
    const command = process.argv[2];
    const args = process.argv.slice(3);

    try {
        switch (command) {
            case 'create':
                if (args.length < 2) {
                    console.error('Usage: node app.js create "title" "description" [status]');
                    process.exit(1);
                }
                const title = args[0];
                const description = args[1];
                const status = args[2] || 'pending';
                const newRequest = createRequest(title, description, status);
                console.log('Created request:', JSON.stringify(newRequest, null, 2));
                break;

            case 'list':
                const requests = listRequests();
                console.log(JSON.stringify(requests, null, 2));
                break;

            case 'filter':
                if (args.length < 1) {
                    console.error('Usage: node app.js filter <status>');
                    process.exit(1);
                }
                const filteredRequests = filterByStatus(args[0]);
                console.log(JSON.stringify(filteredRequests, null, 2));
                break;

            case 'update':
                if (args.length < 2) {
                    console.error('Usage: node app.js update <id> <newStatus>');
                    process.exit(1);
                }
                const updatedRequest = updateStatus(args[0], args[1]);
                console.log('Updated request:', JSON.stringify(updatedRequest, null, 2));
                break;

            default:
                console.error('Invalid command. Use create, list, filter, or update.');
                process.exit(1);
        }
    } catch (error) {
        console.error('Error:', error.message);
        process.exit(1);
    }
}

// Export functions for use as a module
module.exports = {
    createRequest,
    listRequests,
    filterByStatus,
    updateStatus
};

const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const path = require('path');
const { createRequest, listRequests, filterByStatus, updateStatus } = require('./app.js');

const dataFilePath = path.join(__dirname, 'data.json');

// Helper function to reset data.json
const resetData = () => {
    fs.writeFileSync(dataFilePath, JSON.stringify([]));
};

// Run before each test
test.beforeEach(() => {
    resetData();
});

test.describe('createRequest', () => {
    test('should create a new request with valid data', () => {
        const request = createRequest('Test Request', 'This is a test request', 'pending');
        assert.strictEqual(request.title, 'Test Request');
        assert.strictEqual(request.description, 'This is a test request');
        assert.strictEqual(request.status, 'pending');
        assert.ok(request.id);
        assert.ok(request.createdAt);
    });

    test('should throw error for empty title', () => {
        assert.throws(() => createRequest('', 'Description'), Error);
    });

    test('should throw error for empty description', () => {
        assert.throws(() => createRequest('Title', ''), Error);
    });

    test('should throw error for invalid status', () => {
        assert.throws(() => createRequest('Title', 'Description', 'invalid-status'), Error);
    });
});

test.describe('listRequests', () => {
    test('should return an empty array when no requests exist', () => {
        const requests = listRequests();
        assert.strictEqual(Array.isArray(requests), true);
        assert.strictEqual(requests.length, 0);
    });

    test('should return all requests', () => {
        createRequest('Request 1', 'Description 1');
        createRequest('Request 2', 'Description 2', 'in-progress');
        const requests = listRequests();
        assert.strictEqual(requests.length, 2);
        assert.strictEqual(requests[0].title, 'Request 1');
        assert.strictEqual(requests[1].title, 'Request 2');
    });
});

test.describe('filterByStatus', () => {
    test('should filter requests by status', () => {
        createRequest('Request 1', 'Description 1', 'pending');
        createRequest('Request 2', 'Description 2', 'in-progress');
        createRequest('Request 3', 'Description 3', 'pending');

        const pendingRequests = filterByStatus('pending');
        assert.strictEqual(pendingRequests.length, 2);
        assert.strictEqual(pendingRequests[0].title, 'Request 1');
        assert.strictEqual(pendingRequests[1].title, 'Request 3');
    });

    test('should throw error for invalid status', () => {
        assert.throws(() => filterByStatus('invalid-status'), Error);
    });
});

test.describe('updateStatus', () => {
    test('should update request status', () => {
        const request = createRequest('Test Request', 'This is a test request', 'pending');
        const updatedRequest = updateStatus(request.id, 'in-progress');

        assert.strictEqual(updatedRequest.status, 'in-progress');
        assert.ok(updatedRequest.updatedAt);
    });

    test('should throw error for non-existent ID', () => {
        assert.throws(() => updateStatus('non-existent-id', 'in-progress'), Error);
    });

    test('should throw error for invalid status', () => {
        const request = createRequest('Test Request', 'This is a test request');
        assert.throws(() => updateStatus(request.id, 'invalid-status'), Error);
    });
});

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const dataFile = path.join(__dirname, 'data.json');

// Initialize data.json if it doesn't exist
if (!fs.existsSync(dataFile)) {
    fs.writeFileSync(dataFile, JSON.stringify([]));
}

// Load existing data
function loadData() {
    try {
        const data = fs.readFileSync(dataFile, 'utf8');
        return JSON.parse(data);
    } catch (error) {
        console.error('Error loading data:', error);
        return [];
    }
}

// Save data to file
function saveData(data) {
    try {
        fs.writeFileSync(dataFile, JSON.stringify(data, null, 2));
    } catch (error) {
        console.error('Error saving data:', error);
    }
}

// Validate status
function isValidStatus(status) {
    const validStatuses = ['pending', 'in-progress', 'resolved', 'rejected'];
    return validStatuses.includes(status);
}

// Create a new request
function createRequest(title, desc, status = 'pending') {
    if (!title || title.trim() === '') {
        throw new Error('Title cannot be empty');
    }
    if (!desc || desc.trim() === '') {
        throw new Error('Description cannot be empty');
    }
    if (!isValidStatus(status)) {
        throw new Error('Invalid status');
    }

    const requests = loadData();
    const newRequest = {
        id: Date.now().toString(),
        title,
        desc,
        status,
        createdAt: new Date().toISOString()
    };

    requests.push(newRequest);
    saveData(requests);
    return newRequest;
}

// List all requests
function listRequests() {
    return loadData();
}

// Filter requests by status
function filterByStatus(status) {
    if (!isValidStatus(status)) {
        throw new Error('Invalid status');
    }

    const requests = loadData();
    return requests.filter(request => request.status === status);
}

// Update request status
function updateStatus(id, newStatus) {
    if (!isValidStatus(newStatus)) {
        throw new Error('Invalid status');
    }

    const requests = loadData();
    const requestIndex = requests.findIndex(request => request.id === id);

    if (requestIndex === -1) {
        throw new Error('Request not found');
    }

    requests[requestIndex].status = newStatus;
    requests[requestIndex].updatedAt = new Date().toISOString();
    saveData(requests);
    return requests[requestIndex];
}

// CLI functionality
function main() {
    const args = process.argv.slice(2);

    if (args.length < 1) {
        console.log('Usage:');
        console.log('  node app.js create <title> <description> [status]');
        console.log('  node app.js list');
        console.log('  node app.js filter <status>');
        console.log('  node app.js update <id> <newStatus>');
        return;
    }

    const command = args[0];

    try {
        switch (command) {
            case 'create':
                if (args.length < 3) {
                    console.log('Error: Not enough arguments for create command');
                    console.log('Usage: node app.js create <title> <description> [status]');
                    return;
                }
                const title = args[1];
                const desc = args[2];
                const status = args[3] || 'pending';
                const newRequest = createRequest(title, desc, status);
                console.log('Request created:', JSON.stringify(newRequest, null, 2));
                break;

            case 'list':
                const requests = listRequests();
                console.log(JSON.stringify(requests, null, 2));
                break;

            case 'filter':
                if (args.length < 2) {
                    console.log('Error: Not enough arguments for filter command');
                    console.log('Usage: node app.js filter <status>');
                    return;
                }
                const filterStatus = args[1];
                const filteredRequests = filterByStatus(filterStatus);
                console.log(JSON.stringify(filteredRequests, null, 2));
                break;

            case 'update':
                if (args.length < 3) {
                    console.log('Error: Not enough arguments for update command');
                    console.log('Usage: node app.js update <id> <newStatus>');
                    return;
                }
                const id = args[1];
                const newStatus = args[2];
                const updatedRequest = updateStatus(id, newStatus);
                console.log('Request updated:', JSON.stringify(updatedRequest, null, 2));
                break;

            default:
                console.log('Unknown command:', command);
                console.log('Available commands: create, list, filter, update');
        }
    } catch (error) {
        console.error('Error:', error.message);
    }
}

// Export functions for testing
module.exports = {
    createRequest,
    listRequests,
    filterByStatus,
    updateStatus,
    loadData,
    saveData,
    isValidStatus
};

// Run CLI if called directly
if (require.main === module) {
    main();
}

const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const path = require('path');
const app = require('./app.js');

// Helper function to reset data.json
function resetData() {
    fs.writeFileSync(path.join(__dirname, 'data.json'), JSON.stringify([]));
}

test.describe('Municipal Service Request Tracker', () => {
    test.beforeEach(() => {
        resetData();
    });

    test.describe('createRequest', () => {
        test('should create a new request with valid data', () => {
            const request = app.createRequest('Test Title', 'Test Description', 'pending');
            assert.strictEqual(request.title, 'Test Title');
            assert.strictEqual(request.desc, 'Test Description');
            assert.strictEqual(request.status, 'pending');
            assert.ok(request.id);
            assert.ok(request.createdAt);
        });

        test('should throw error for empty title', () => {
            assert.throws(() => {
                app.createRequest('', 'Test Description');
            }, Error);
        });

        test('should throw error for empty description', () => {
            assert.throws(() => {
                app.createRequest('Test Title', '');
            }, Error);
        });

        test('should throw error for invalid status', () => {
            assert.throws(() => {
                app.createRequest('Test Title', 'Test Description', 'invalid-status');
            }, Error);
        });

        test('should default status to pending when not provided', () => {
            const request = app.createRequest('Test Title', 'Test Description');
            assert.strictEqual(request.status, 'pending');
        });
    });

    test.describe('listRequests', () => {
        test('should return an empty array when no requests exist', () => {
            const requests = app.listRequests();
            assert.strictEqual(Array.isArray(requests), true);
            assert.strictEqual(requests.length, 0);
        });

        test('should return all requests', () => {
            app.createRequest('Title 1', 'Description 1', 'pending');
            app.createRequest('Title 2', 'Description 2', 'in-progress');
            const requests = app.listRequests();
            assert.strictEqual(requests.length, 2);
            assert.strictEqual(requests[0].title, 'Title 1');
            assert.strictEqual(requests[1].title, 'Title 2');
        });
    });

    test.describe('filterByStatus', () => {
        test('should throw error for invalid status', () => {
            assert.throws(() => {
                app.filterByStatus('invalid-status');
            }, Error);
        });

        test('should return empty array when no requests match the status', () => {
            app.createRequest('Title 1', 'Description 1', 'pending');
            const requests = app.filterByStatus('resolved');
            assert.strictEqual(requests.length, 0);
        });

        test('should return only requests with matching status', () => {
            app.createRequest('Title 1', 'Description 1', 'pending');
            app.createRequest('Title 2', 'Description 2', 'in-progress');
            app.createRequest('Title 3', 'Description 3', 'pending');
            const requests = app.filterByStatus('pending');
            assert.strictEqual(requests.length, 2);
            assert.strictEqual(requests[0].title, 'Title 1');
            assert.strictEqual(requests[1].title, 'Title 3');
        });
    });

    test.describe('updateStatus', () => {
        test('should throw error for invalid status', () => {
            const request = app.createRequest('Test Title', 'Test Description', 'pending');
            assert.throws(() => {
                app.updateStatus(request.id, 'invalid-status');
            }, Error);
        });

        test('should throw error for non-existent request', () => {
            assert.throws(() => {
                app.updateStatus('non-existent-id', 'in-progress');
            }, Error);
        });

        test('should update request status successfully', () => {
            const request = app.createRequest('Test Title', 'Test Description', 'pending');
            const updatedRequest = app.updateStatus(request.id, 'in-progress');
            assert.strictEqual(updatedRequest.status, 'in-progress');
            assert.ok(updatedRequest.updatedAt);

            // Verify the change persisted
            const requests = app.listRequests();
            assert.strictEqual(requests[0].status, 'in-progress');
        });
    });
});
